 [STAThread]static int Main(){try{_=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Directory.CreateDirectory("analysis/distortion-calibration/reset-source-list/checks");Scenario(false,false);Scenario(true,false);Scenario(false,true);Scenario(false,false,true);File.WriteAllText("analysis/distortion-calibration/reset-source-list/checks/summary.json",JsonSerializer.Serialize(new{passed=true,checks,nativeExecution=false}));Console.WriteLine($"PASS {checks} distortion original15-default/13ISub reset checks");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Scenario(bool rejectDefault,bool rejectClear,bool persistedOnly=false){var plugin=new DistortionCalibrationPlugin();using var scope=new ModuleExecutionScope();var backing=DistortionCalibrationMetadata.Defaults();backing["CalibPathName"]=J(Path.GetFullPath("analysis/distortion-calibration/reset-source-list/keep.iccal"));backing["RefreshFileEnable"]=J(true);backing["HomoFreedom"]=J(3);backing["CorrectModel"]=J(2);backing["CalibBoardType"]=J(8);backing["WeightFactor"]=J(35);var mode=SubNames.ToDictionary(n=>"@"+n,_=>"True");mode["Param.CorrectCenterPointInput"]="1";mode["KeepUnknown"]="keep";backing["ConfigurationUserData"]=J(JsonSerializer.Serialize(mode));backing["DisplaySettings"]=ToolDisplayService.Serialize(new("keep-content","#123456","#654321",17,.75,41,42));string display=backing["DisplaySettings"].GetRawText(),path=backing["CalibPathName"].GetString()!;
