 sealed class Subscriptions:IToolConfigurationSubscriptionService{public Dictionary<string,ConfigurationSubscriptionBinding> Bindings=[];public List<string> Clears=[];public string? Reject;public ConfigurationSubscriptionTreeResult Enumerate(ConfigurationSubscriptionQuery q)=>new(ConfigurationSubscriptionStatus.Available,[]);public ConfigurationSubscriptionBindingResult Read(ConfigurationSubscriptionDestination d)=>new(ConfigurationSubscriptionStatus.Available,Bindings.GetValueOrDefault(d.Name),Bindings.TryGetValue(d.Name,out var b)?((ConfigurationConstantReference)b.Reference).Literal:"");public ConfigurationSubscriptionBindingResult Bind(ConfigurationSubscriptionDestination d,ConfigurationSubscriptionBinding? b){if(b is null){Clears.Add(d.Name);if(d.Name==Reject)return new(ConfigurationSubscriptionStatus.Failed,Bindings.GetValueOrDefault(d.Name),Diagnostic:"host rejected clear");Bindings.Remove(d.Name);}else Bindings[d.Name]=b;return Read(d);}}
